INSERT INTO `psy_scale` VALUES (4, '睡眠状况自评量表', 'SRSS', '用于评定睡眠质量与睡眠障碍情况。五级评分，总分越高提示睡眠问题越突出。', 5, '0', 4, '2026-09-14 17:06:33', '2026-09-14 17:06:33');
