INSERT INTO `psy_test_record` VALUES (3, 3, 3, 100, 100.0, '重度症状', '存在重度心理症状。强烈建议尽快前往正规医疗机构精神心理科就诊，接受系统诊断与治疗；紧急时可拨打全国心理援助热线 12356 求助。', '1', '2026-09-14 19:43:27');
INSERT INTO `psy_test_record` VALUES (4, 3, 4, 92, 92.0, '重度睡眠问题', '存在重度睡眠问题。建议尽快前往医院睡眠医学科或心理精神科就诊，接受专业评估与治疗，避免长期依赖安眠药物。', '1', '2026-09-14 19:44:44');
INSERT INTO `psy_test_record` VALUES (5, 3, 1, 49, 61.3, '中度焦虑', '存在中度焦虑倾向。建议尽快前往心理门诊或精神心理科进行专业评估，可配合认知行为训练与专业心理治疗，避免长期处于高压状态。', '1', '2026-09-15 09:29:49');
INSERT INTO `psy_test_record` VALUES (6, 3, 1, 46, 57.5, '轻度焦虑', '存在轻度焦虑倾向。建议通过运动锻炼、呼吸放松、社交倾诉等方式自我调节，注意劳逸结合，必要时可寻求心理咨询支持。', '1', '2026-09-15 10:03:11');
INSERT INTO `psy_test_record` VALUES (7, 4, 1, 62, 77.5, '重度焦虑', '存在重度焦虑倾向。强烈建议尽快前往正规医疗机构心理科或精神科就诊，接受专业诊断与干预；也可拨打全国心理援助热线 12356 寻求即时支持。', '1', '2026-09-15 14:13:30');
INSERT INTO `psy_test_record` VALUES (8, 4, 3, 79, 79.0, '重度症状', '存在重度心理症状。强烈建议尽快前往正规医疗机构精神心理科就诊，接受系统诊断与治疗；紧急时可拨打全国心理援助热线 12356 求助。', '1', '2026-09-15 15:35:15');
INSERT INTO `psy_test_record` VALUES (9, 5, 5, 8, 8.0, '正常', '测评完成，请结合自身情况关注心理健康。', '1', '2026-09-20 08:29:43');
INSERT INTO `psy_test_record` VALUES (10, 5, 4, 53, 53.0, '轻度睡眠问题', '存在轻度睡眠问题。建议固定就寝与起床时间，睡前避免咖啡浓茶与剧烈运动，可通过温水泡脚、听轻音乐等方式助眠。', '1', '2026-09-20 11:59:39');
